	rt = container_of(head, struct mpls_route, rt_rcu);

	change_nexthops(rt) {
		netdev_put(nh->nh_dev, &nh->nh_dev_tracker);
	} endfor_nexthops(rt);

	kfree(rt);
}

static void mpls_rt_free(struct mpls_route *rt)
{
	if (rt)
		call_rcu(&rt->rt_rcu, mpls_rt_free_rcu);
